#include <stdio.h>
#include <math.h>
int main(){
FILE*o=fopen("reconstructed.ppm","w");
fprintf(o,"P3\n2400 1800\n255\n");
for(int y=0;y<1800;y++)for(int x=0;x<2400;x++){
double dx=x+.5-1200,dy=900-y-.5,dz=900,n=sqrt(dx*dx+dy*dy+dz*dz);
dx/=n;dy/=n;dz/=n;
double r,g,b;
double bb=-.5*dy+(-5)*dz+0; /* D.(0,-.5,5) */
bb=-.5*dy+5*dz;
double disc=bb*bb-(25.25-1),t=-1;
if(disc>=0)t=bb-sqrt(disc);
if(t>0){
double nx=dx*t,ny=dy*t+.5,nz=dz*t-5;
double d=(nx+ny+nz)/1.7320508;if(d<0)d=0;
double m=.2+.8*d;r=m;g=m*.2;b=m*.2;
}else if(dy<0){
double z=-1.5/dy,X=dx*z,Z=dz*z+(y>900?-1e-6:1e-6);
int l=((int)floor(X)+(int)floor(Z))&1;
double c=l?152/255.:67/255.;
double px=X,py=-1.5,pz=Z,s=.57735027;
double qy=py+.5,qz=pz-5,q=s*(px+qy+qz);
double h=q*q-(px*px+qy*qy+qz*qz-1);
if(h>0&&q<0)c*=.3;
r=g=b=c;
}else{
double u=dy;r=.75-.25*u;g=.85-.15*u;b=1;
}
fprintf(o,"%d %d %d\n",(int)(r*255+.5),(int)(g*255+.5),(int)(b*255+.5));
}
fclose(o);}
